'use strict';
const $=id=>document.getElementById(id);let timer=null;
const labels={idle:'Можно начать официальный вход.',starting:'Запускаем официальный agy…',waiting_for_code:'Открой Google, выполни вход и вставь выданный одноразовый код.',validating:'Официальный agy проверяет вход…',authenticated:'✓ Вход выполнен · Google Antigravity. Можно вернуться к GoBot.',login_failed:'Вход не завершён. Попробуй начать заново.',cancelled:'Вход отменён.'};
async function status(){try{const response=await fetch('/api/settings/google'),data=await response.json();$('status').textContent=labels[data.state]||data.state;$('authorize').hidden=!data.authorization_url;if(data.authorization_url)$('authorize').href=data.authorization_url;$('code-form').hidden=data.state!=='waiting_for_code';$('login').disabled=['starting','waiting_for_code','validating'].includes(data.state);if(!['starting','waiting_for_code','validating'].includes(data.state)){clearInterval(timer);timer=null;}}catch(_){$('status').textContent='Нет связи с сервером.';}}
$('login').onclick=async()=>{await fetch('/api/settings/google/start',{method:'POST'});if(!timer)timer=setInterval(status,1000);await status();};
$('code-form').onsubmit=async event=>{event.preventDefault();const value=$('code').value;$('code').value='';const response=await fetch('/api/settings/google/code',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:value})});if(!response.ok)$('status').textContent='Код не принят или срок входа истёк.';else await status();};
$('cancel').onclick=async()=>{await fetch('/api/settings/google/cancel',{method:'POST'});await status();};status();
